export const ROUTES={dziennik:'Dziennik',przepisy:'Przepisy',produkty:'Produkty',historia:'Historia',wiecej:'Więcej'};
export function routeFromHash(hash){const key=hash.replace(/^#\/?/,'');return Object.hasOwn(ROUTES,key)?key:'dziennik';}
export function navigate(route){if(!Object.hasOwn(ROUTES,route))route='dziennik';if(location.hash!==`#/${route}`)location.hash=`/${route}`;window.dispatchEvent(new Event('hashchange'));}
export function initNavigation(){
 let current=null;
 function render(){const route=routeFromHash(location.hash);if(location.hash!==`#/${route}`)history.replaceState(null,'',`#/${route}`);
  for(const section of document.querySelectorAll('[data-app-section]'))section.hidden=section.dataset.appSection!==route;
  for(const link of document.querySelectorAll('#app-nav [data-route]')){if(link.dataset.route===route)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');}
  document.title=`Benger · ${ROUTES[route]}`;
  if(current!==null&&current!==route)window.scrollTo(0,0);
  if(current!==null&&current!==route)document.querySelector(`[data-app-section="${route}"] [data-route-heading]`)?.focus({preventScroll:true});
  const previous=current;current=route;document.documentElement.dataset.route=route;window.dispatchEvent(new CustomEvent('benger:route',{detail:{route,previous}}));
 }
 window.addEventListener('hashchange',render);render();return {navigate,current:()=>current};
}

